const PHASE = process.env.EDGE_PHASE === 'FULL' ? 'FULL' : 'DEV';
const HERE = dirname(fileURLToPath(import.meta.url)); const REPO = join(HERE, '..', '..', '..'); const ROOT = join(REPO, 'research', 'trade_economics_v5'); const OUT = join(ROOT, 'results'); const CFG = join(ROOT, 'configs'); mkdirSync(OUT, { recursive: true }); mkdirSync(CFG, { recursive: true });
const shaFile = (p) => createHash('sha256').update(readFileSync(p)).digest('hex');
const PREREG_SHA = readFileSync(join(ROOT, 'V5_PREREGISTRATION.sha256'), 'utf8').trim().split(/\s+/)[0]; if (shaFile(join(ROOT, 'V5_PREREGISTRATION.md')) !== PREREG_SHA) throw new Error('V5_PREREGISTRATION hash mismatch');
const CONTROL_SHA = readFileSync(join(ROOT, 'V5_CONTROL_BASELINE.sha256'), 'utf8').trim().split(/\s+/)[0]; if (shaFile(join(ROOT, 'V5_CONTROL_BASELINE.md')) !== CONTROL_SHA) throw new Error('V5_CONTROL_BASELINE hash mismatch');
const LAB = join(REPO, 'handoff', 'edge_discovery_lab', 'data');
