const C = readFileSync(join(REPO, 'research', 'entry_architecture_v2', 'results', 'candidates.jsonl'), 'utf8').trim().split('\n').map((l) => JSON.parse(l)).filter((c) => split(c.t) !== 'EXCLUDED');
const V4 = buildV4(b5, ROWS, { split, day, SPLIT, FIRST_I, LAST_I }); const F = V4.F;
