const POP = {}; POP.CONTROL = C.filter((c) => c.act === 'BUY' || c.act === 'SELL').map((c) => ({ i: c.i, t: c.t, side: c.side, fam: 'CONTROL', model: c.model, anchor: c.anchor ?? c.geo.entry, geo: { entry: c.geo.entry, sl: c.geo.sl, tp2: c.geo.tp2 }, prod_rr: c.geo.rr, atr: c.atr, atrR: c.atrR, anchor_disp_atr: c.overext_atr, rg5: c.rg5, ses: c.ses, m30r: c.m30r, h1r: c.h1r, split: split(c.t), pop: 'CONTROL' }));
