for (const [k, v] of Object.entries(POP)) for (const e of v) { e.risk = Math.abs(e.geo.entry - e.geo.sl); e.riskAtr = r3(e.risk / e.atr); e.disp = r3(Math.abs(e.geo.entry - (e.side === 'BUY' ? F.lo12[e.i] : F.hi12[e.i])) / e.atr); e.rangePos = F.hi12[e.i] != null ? r3((e.geo.entry - Math.min(...b5.slice(e.i - 23, e.i + 1).map((b) => b.low))) / Math.max(1e-9, Math.max(...b5.slice(e.i - 23, e.i + 1).map((b) => b.high)) - Math.min(...b5.slice(e.i - 23, e.i + 1).map((b) => b.low)))) : null; e.dSH = F.dSH[e.i]; e.dSL = F.dSL[e.i]; e.tp_r = r3(Math.abs(e.geo.tp2 - e.geo.entry) / e.risk); }
console.log(`phase ${PHASE}; populations ${Object.entries(POP).map(([k, v]) => `${k}:${v.length}`).join(' ')}`);
const MEANINGFUL = ['CONTROL', 'S2', 'S3', 'S4']; const ALLPOP = Object.keys(POP);

// ---------- policies ----------
const refPolicy = (pop) => (pop === 'CONTROL' ? { ref: 'PROD_TP2' } : { rr: 1.7 });
function withRef(pop, spec) { const p = { ...spec }; if (p.type !== 'FIXED' && p.type !== 'OPEN' && p.type !== 'HARVEST' && p.type !== 'STRUCT_TRAIL') { if (pop === 'CONTROL') p.useProdTp = true; else p.rr = 1.7; } return p; }
const POLICIES = [{ key: 'OPEN', type: 'OPEN' }]; for (const rr of [0.5, 0.75, 1, 1.25, 1.5, 1.7, 2, 2.5, 3]) POLICIES.push({ key: `FIXED|rr${rr}`, type: 'FIXED', rr, family: 'FIXED' }); for (const m of [0.5, 0.75, 1]) POLICIES.push({ key: `BE|m${m}`, type: 'BE', m, family: 'BE' }); for (const m of [0.5, 0.75, 1]) POLICIES.push({ key: `PARTIAL|m${m}`, type: 'PARTIAL', m, protect: 0.5, family: 'PARTIAL' }); for (const m of [1, 1.25, 1.5]) POLICIES.push({ key: `FLOOR|m${m}`, type: 'FLOOR', m, floor: m - 0.5, family: 'FLOOR' }); for (const arm of [1, 1.5]) for (const gap of [0.5, 0.75, 1]) POLICIES.push({ key: `HARVEST|a${arm}|g${gap}`, type: 'HARVEST', arm, gap, family: 'HARVEST' }); POLICIES.push({ key: 'STRUCT_TRAIL', type: 'STRUCT_TRAIL', family: 'STRUCT_TRAIL' }); for (const bars of [3, 6]) POLICIES.push({ key: `TIME|b${bars}`, type: 'TIME', bars, level: 0.5, family: 'TIME' });
const swingAt = (j, side) => { const sw = side === 'BUY' ? F.lastSL[j] : F.lastSH[j]; return sw ? sw.price : null; };
const MEMO = new Map();
function run(e, pol, cse = 'normal', drift = false) { const key = `${e.pop}|${e.i}|${e.side}|${pol.key}|${cse}|${drift}`; const m = MEMO.get(key); if (m) return m; const p = { ...pol }; if (p.useProdTp) p.tpPrice = e.geo.tp2; if (p.type === 'STRUCT_TRAIL') p.swingAt = swingAt; const o = simulate(b5, e, p, COSTS[cse], { drift }); MEMO.set(key, o); return o; }
