function stats(rows, sessSet = null, { ci = true, block = false } = {}) { const R = rows.map((x) => x.o.r); if (!R.length) return { n: 0 }; const w = R.filter((x) => x > 0), l = R.filter((x) => x <= 0); const gw = w.reduce((a, b) => a + b, 0), gl = -l.reduce((a, b) => a + b, 0); const U = rows.map((x) => x.o.pnl_usd); const perDay = {}; for (const x of rows) perDay[day(x.e.t)] = (perDay[day(x.e.t)] ?? 0) + 1; const counts = sessSet ? [...sessSet].map((d) => perDay[d] ?? 0) : null; const costU = rows.reduce((s, x) => s + x.o.cost_usd, 0); const ddR = pathDD(rows, 'r'), ddU = pathDD(rows, 'pnl_usd'); const gb = rows.filter((x) => x.o.mfe_r >= 0.5).map((x) => x.o.mfe_r - x.o.r); const ex = {}; for (const x of rows) ex[x.o.exit] = (ex[x.o.exit] ?? 0) + 1;
  return { n: R.length, win_rate: r3(w.length / R.length), avg_win_r: r3(mean(w)), avg_loss_r: l.length ? r3(-mean(l)) : null, expectancy_r: r3(mean(R)), expectancy_usd: r3(mean(U)), gross_expectancy_usd: r3(mean(U) + costU / R.length), pf: gl > 0 ? r2(gw / gl) : (gw > 0 ? 99 : null), ci95_r: ci ? bootCI(R) : null, ci99_r: ci ? bootCI(R, 2000, 20260930, 0.01) : null, block_ci95_r: block ? blockCI(rows) : null, block_ci99_r: block ? blockCI(rows, 2000, 7, 0.01) : null, max_dd_r: ddR.max_dd, max_dd_usd: ddU.max_dd, net_r: ddR.final, net_usd: ddU.final, max_loss_streak: ddR.max_loss_streak, trades_to_new_high_max: ddR.max_trades_to_new_high, mfe_r: r3(mean(rows.map((x) => x.o.mfe_r))), mae_r: r3(mean(rows.map((x) => x.o.mae_r))), mae3_r: r3(mean(rows.map((x) => x.o.mae3_r))), avg_bars: r2(mean(rows.map((x) => x.o.bars))), median_bars: median(rows.map((x) => x.o.bars)), cost_usd: r3(costU / R.length), cost_r: r3(mean(rows.map((x) => x.o.cost_r))), cost_pct_gross: (mean(U) + costU / R.length) > 0 ? r3((costU / R.length) / (mean(U) + costU / R.length)) : null, giveback_r_mean: r3(mean(gb)), giveback_share: r3(gb.length / R.length), trades_per_session: counts ? { median: pct(counts, 0.5), p90: pct(counts, 0.9), mean: r2(mean(counts)) } : null, zero_trade_session_rate: counts ? r3(counts.filter((x) => x === 0).length / counts.length) : null, top5_share: gw > 0 ? r3([...R].sort((a, b) => b - a).slice(0, 5).filter((x) => x > 0).reduce((s, x) => s + x, 0) / gw) : null, exit_mix: Object.fromEntries(Object.entries(ex).map(([k, v]) => [k, r3(v / R.length)])), risk_usd_mean: r3(mean(rows.map((x) => x.e.risk))), risk_atr_median: r3(median(rows.map((x) => x.e.riskAtr))) }; }
const cell = (rows) => { const s = stats(rows, null, { ci: rows.length >= 30 }); return { n: s.n ?? 0, win_rate: s.win_rate, avg_win_r: s.avg_win_r, avg_loss_r: s.avg_loss_r, expectancy_r: s.expectancy_r, expectancy_usd: s.expectancy_usd, pf: s.pf, max_dd_r: s.max_dd_r, mfe_r: s.mfe_r, mae_r: s.mae_r, mae3_r: s.mae3_r, median_bars: s.median_bars, ci95_r: s.ci95_r }; };
const byGroup = (rows, keyFn, extra = null) => { const g = {}; for (const x of rows) (g[keyFn(x)] ??= []).push(x); return Object.fromEntries(Object.entries(g).sort((a, b) => b[1].length - a[1].length).map(([k, v]) => [k, extra ? { ...cell(v), ...extra(v) } : cell(v)])); };
